days=np.arange(1,61); spread=np.full_like(days,0.80,dtype=float); costs=0.12*days+0.10*np.sqrt(days); net=spread-costs; ax.plot(days,spread,label='Gross spread (cents)',color=ACCENT,lw=2); ax.plot(days,costs,label='Holding cost (cents)',color=BAD,lw=2); ax.plot(days,net,label='Net after cost (cents)',color=GOOD,lw=2); ax.axhline(0,color=INK,lw=.8); ax.set_xlabel('Holding horizon (days)'); ax.set_ylabel('USD cents/share'); ax.set_title('Illustrative arbitrage economics',loc='left'); ax.legend(fontsize=7); ax.grid(alpha=.25)
